type Row = Record<string, any>;

function presentation(value:any):any{
 if(Array.isArray(value))return value.map(presentation);
 if(!value||typeof value!=='object')return value;
 return Object.fromEntries(Object.entries(value).map(([key,v])=>{
  if(['display_name','name','title','factual_summary','assignee_name'].includes(key)&&typeof v==='string'){
   v=v.replace(/^Demo Miami-style Habitat (\d+)$/,'Miami Colony Habitat $1').replace(/^Synthetic care coordination need$/,'Care Coordination Need').replace(/^Synthetic care action (\d+)$/,'Care Action $1').replace(/^Demo Coordinator /,'Coordinator ').replace(/^Demo Volunteer /,'Volunteer ').replace(/^Fictional Cat /,'Cat ');
   return [key,v];
  }
  return [key,presentation(v)];
 }));
}

