function Brand(){return <div className="brand"><div className="brand-icon"><img className="brand-icon-image" src="/brand/zeus-watch-icon.png" alt="" aria-hidden="true"/></div><div><strong>ZEUS WATCH</strong><small>Every colony supported</small></div></div>}
function Empty({title,body}:{title:string;body:string}){return <div className="empty"><Leaf size={29}/><h3>{title}</h3><p>{body}</p></div>}

